//! The C ABI of cleanrules (`include/cleanrules.h`, generated by cbindgen).
//!
//! C, C++, Go and the JVM reach the core through these functions. They are a
//! thin layer (CLAUDE.md, invariant 2): they read arguments, call the core and
//! hand back handles, JSON and errors. The conventions are those of the
//! header's preamble (`cbindgen.toml`) and of `README.md`.
//!
//! # ABI versions
//!
//! `CR_ABI_VERSION` is the version of this ABI that the header describes, and
//! `cr_abi_version` the one the library implements; a program checks that they
//! are equal. Adding functions or constants keeps the version; changing or
//! removing one, or the meaning of a number, raises it.

// The ABI's names are C's.
#![allow(non_camel_case_types)]

pub mod decision;
pub mod document;
pub mod error;
pub mod limits;
pub mod ruleset;
pub mod value;

mod boundary;

use std::ffi::{CStr, CString, c_char};

pub use decision::*;
pub use document::*;
pub use error::*;
pub use limits::*;
pub use ruleset::*;
pub use value::*;

/// The version of the ABI that this header describes.
pub const CR_ABI_VERSION: u32 = 1;

/// What a fallible function returns: `CR_OK`, an error code (`CR_FORMAT_ERROR`,
/// `CR_MISSING_FIELD`, ...), `CR_INVALID_ARGUMENT` or `CR_INTERNAL_ERROR`.
pub type cr_status = i32;

/// Success.
pub const CR_OK: cr_status = 0;
/// The caller broke the ABI's rules: a `NULL` where a pointer is required, or
/// an unknown format or limit. The message names the function.
pub const CR_INVALID_ARGUMENT: cr_status = -1;
/// A bug in cleanrules, caught at the boundary: please report it.
pub const CR_INTERNAL_ERROR: cr_status = -2;

/// A syntax documents are read from and written in (`CR_FORMAT_*`).
pub type cr_format = i32;

/// JSON (`spec/json-format.md`).
pub const CR_FORMAT_JSON: cr_format = 1;
/// YAML (`spec/json-format.md`, *YAML*).
pub const CR_FORMAT_YAML: cr_format = 2;
/// The rule syntax (`spec/text.md`); for explanations and summaries, their text.
pub const CR_FORMAT_TEXT: cr_format = 3;
/// CSV, for decision tables (`spec/tables.md`).
pub const CR_FORMAT_CSV: cr_format = 4;

// The handles are shared between threads, as the header promises.
const _: () = {
    const fn shared<T: Send + Sync>() {}
    shared::<cr_document>();
    shared::<cr_ruleset>();
    shared::<cr_decision>();
    shared::<cr_limits>();
    shared::<cr_error>();
    shared::<cleanrules::Value>();
};

/// The version of the ABI that the library implements: `CR_ABI_VERSION` of
/// the header it was built with.
#[unsafe(no_mangle)]
pub extern "C" fn cr_abi_version() -> u32 {
    CR_ABI_VERSION
}

/// The version of the JSON format the library reads and writes.
#[unsafe(no_mangle)]
pub extern "C" fn cr_format_version() -> u32 {
    cleanrules::FORMAT_VERSION
}

/// The library's version, such as `0.1.0`: a static string, never freed.
#[unsafe(no_mangle)]
pub extern "C" fn cr_version() -> *const c_char {
    const VERSION: &CStr =
        match CStr::from_bytes_with_nul(concat!(env!("CARGO_PKG_VERSION"), "\0").as_bytes()) {
            Ok(version) => version,
            Err(_) => c"",
        };
    VERSION.as_ptr()
}

/// Free a text returned through a `char **out` parameter. `NULL` is ignored.
/// Never pass it the strings of `cr_error_*`, `cr_version` or `cr_status_name`.
///
/// # Safety
///
/// `text` is `NULL` or a text from a `char **out` parameter of this library,
/// not freed before.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn cr_string_free(text: *mut c_char) {
    if !text.is_null() {
        // SAFETY: the caller promises that `text` came from `CString::into_raw`
        // in this library and was not freed.
        drop(unsafe { CString::from_raw(text) });
    }
}
